import{_ as p,a0 as o,w as d,s as r,ao as l,I as t,a1 as i,A as n,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"通過詢問-響應身份認證提高桌面登錄安全 | LCTT x X-CMD","titleTemplate":false,"description":"通過詢問-響應身份認證提高桌面登錄安全 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過詢問-響應身份認證提高桌面登錄安全 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過詢問-響應身份認證提高桌面登錄安全 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181022 Improve login security with challenge-response authentication","title":"通過詢問-響應身份認證提高桌面登錄安全","tag":"201812","desc":""},"relativePath":"201812/20181022 Improve login security with challenge-response authentication.md","filePath":"[post].md"}'),h={name:"201812/20181022 Improve login security with challenge-response authentication.md"};function c(u,e,g,k,b,y){const a=o("Link");return d(),r("div",null,[e[17]||(e[17]=l('<h1 id="通過詢問-響應身份認證提高桌面登錄安全" tabindex="-1">通過詢問-響應身份認證提高桌面登錄安全 <a class="header-anchor" href="#通過詢問-響應身份認證提高桌面登錄安全" aria-label="Permalink to “通過詢問-響應身份認證提高桌面登錄安全”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/challenge-response-816x345.png" alt=""></p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>今天，Fedora 提供了多種方式來提高我們賬户的身份認證的安全性。當然，它有我們熟悉的用户名密碼登錄方式，它也同樣提供了其他的身份認證選項，比如生物識別、指紋、智能卡、一次性密碼，甚至是<ruby>詢問-響應<rt>challenge-response</rt></ruby>身份認證。</p><p>每種認證方式都有明確的優缺點。這點本身就可以成為一篇相當冗長的文章的主題。Fedora 雜誌之前就已經介紹過了這其中的一些選項：</p>',5)),t("ul",null,[t("li",null,[i(a,{href:"https://fedoramagazine.org/using-the-yubikey4-with-fedora/"},{default:n(()=>[...e[0]||(e[0]=[s("在 Fedora 中使用 YubiKey4",-1)])]),_:1})]),t("li",null,[i(a,{href:"https://fedoramagazine.org/fedora-28-better-smart-card-support-openssh/"},{default:n(()=>[...e[1]||(e[1]=[s("Fedora 28：在 OpenSSH 中更好的支持智能卡",-1)])]),_:1})])]),e[18]||(e[18]=l(`<p>在現在的 Fedora 版本中，最安全的方法之一就是離線硬件詢問-響應。它也同樣是最容易部署的方法之一。下面是具體方法。</p><h3 id="詢問-響應認證" tabindex="-1">詢問-響應認證 <a class="header-anchor" href="#詢問-響應認證" aria-label="Permalink to “詢問-響應認證”">​</a></h3><p>從技術上來講，當你輸入密碼的時候，你就正在響應用户名詢問。離線的詢問、響應包含了這些部分：首先是需要你的用户名，接下來，Fedora 會要你提供一個加密的物理硬件的令牌。令牌會把另一個其存儲的加密密鑰通過<ruby>可插入式身份認證<rt>Pluggable Authentication Module</rt></ruby>模組（PAM）框架來響應詢問。最後，Fedora 才會提示你輸入密碼。這可以防止其他人僅僅使用了找到的硬件令牌，或是隻使用了賬户名密碼而沒有正確的加密密鑰。</p><p>這意味着除了你的賬户名密碼之外，你必須事先在你的操作系統中註冊了一個或多個加密硬件令牌。你必須保證你的物理硬件令牌能夠匹配你的用户名。</p><p>一些詢問-響應的方法，比如一次性密碼（OTP），在硬件令牌上獲取加密的代碼密鑰，然後將這個密鑰通過網絡傳輸到遠程身份認證服務器。然後這個服務器會告訴 Fedora 的 PAM 框架，這是否是該用户的一個有效令牌。如果身份認證服務器在本地網絡上，這個方法非常好。但它的缺點是如果網絡連接斷開或是你在沒有網的遠程端工作。你會被鎖在系統之外，直到你能通過網絡連接到身份認證服務器。</p><p>有時候，生產環境會採用通過 Yubikey 使用一次性密碼（OTP）的設置，然而，在家庭或個人的系統上，你可能更喜歡詢問-響應設置。一切都是本地的，這種方法不需要通過遠程網絡調用。下面這些過程適用於 Fedora 27、28 和 29.</p><h3 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h3><h4 id="硬件令牌密鑰" tabindex="-1">硬件令牌密鑰 <a class="header-anchor" href="#硬件令牌密鑰" aria-label="Permalink to “硬件令牌密鑰”">​</a></h4><p>首先，你需要一個安全的硬件令牌密鑰。具體來説，這個過程需要一個 Yubikey 4、Yubikey NEO，或者是最近發佈的、同樣支持 FIDO2 的 Yubikey 5 系列設備。你應該購買它們中的兩個，一個做備份，以避免其中一個丟失或遭到損壞。你可以在不同的工作地點使用這些密鑰。較為簡單的 FIDO 和 FIDO U2F 版本不適用於這個過程，但是非常適合使用 FIDO 的在線服務。</p><h4 id="備份、備份-以及備份" tabindex="-1">備份、備份，以及備份 <a class="header-anchor" href="#備份、備份-以及備份" aria-label="Permalink to “備份、備份，以及備份”">​</a></h4><p>接下來，為你所有的重要數據製作備份，你可能想在克隆在 VM 裏的 Fedora 27/28/29 裏測試配置，來確保你在設置你自己的個人工作環境之前理解這個過程。</p><h4 id="升級-然後安裝" tabindex="-1">升級，然後安裝 <a class="header-anchor" href="#升級-然後安裝" aria-label="Permalink to “升級，然後安裝”">​</a></h4><p>現在，確定你的 Fedora 是最新的，然後通過 <code>dnf</code> 命令安裝所需要的 Fedora Yubikey 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf upgrade</span></span>
<span class="line"><span>$ sudo dnf install ykclient* ykpers* pam_yubico*</span></span></code></pre></div><p>如果你使用的是 VM 環境，例如 Virtual Box，確保 Yubikey 設備已經插進了 USB 口，然後允許 VM 控制的 USB 訪問 Yubikey。</p><h3 id="配置-yubikey" tabindex="-1">配置 Yubikey <a class="header-anchor" href="#配置-yubikey" aria-label="Permalink to “配置 Yubikey”">​</a></h3><p>確認你的賬户訪問到了 USB Yubikey：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ykinfo -v</span></span>
<span class="line"><span>version: 3.5.0</span></span></code></pre></div><p>如果 Yubikey 沒有被檢測到，會出現下面這些錯誤信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Yubikey core error: no yubikey present</span></span></code></pre></div><p>接下來，通過下面這些 <code>ykpersonalize</code> 命令初始化你每個新的 Yubikey。這將設置 Yubikey 配置插槽 2 使用 HMAC-SHA1 算法（即使少於 64 個字符）進行詢問響應。如果你已經為詢問響應設置好了你的 Yubikey。你就不需要再次運行 <code>ykpersonalize</code> 了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ykpersonalize -2 -ochal-resp -ochal-hmac -ohmac-lt64 -oserial-api-visible</span></span></code></pre></div><p>一些用户在使用的時候將 YubiKey 留在了他們的工作站上，甚至用於對虛擬機進行詢問-響應。然而，為了更好的安全性，你可能會更願意使用手動觸發 YubiKey 來響應詢問。</p><p>要添加手動詢問按鈕觸發器，請添加 <code>-ochal-btn-trig</code> 選項，這個選項可以使得 Yubikey 在請求中閃爍其 LED。等待你在 15 秒內按下硬件密鑰區域上的按鈕來生成響應密鑰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ykpersonalize -2 -ochal-resp -ochal-hmac -ohmac-lt64 -ochal-btn-trig -oserial-api-visible</span></span></code></pre></div><p>為你的每個新的硬件密鑰執行此操作。每個密鑰執行一次。完成編程之後，使用下面的命令將 Yubikey 配置存儲到 <code>~/.yubico</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ykpamcfg -2 -v</span></span>
<span class="line"><span>debug: util.c:222 (check_firmware_version): YubiKey Firmware version: 4.3.4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sending 63 bytes HMAC challenge to slot 2</span></span>
<span class="line"><span>Sending 63 bytes HMAC challenge to slot 2</span></span>
<span class="line"><span>Stored initial challenge and expected response in &#39;/home/chuckfinley/.yubico/challenge-9992567&#39;.</span></span></code></pre></div><p>如果你要設置多個密鑰用於備份，請將所有的密鑰設置為相同，然後使用 <code>ykpamcfg</code> 工具存儲每個密鑰的詢問-響應。如果你在一個已經存在的註冊密鑰上運行 <code>ykpersonalize</code> 命令，你就必須再次存儲配置信息。</p><h3 id="配置-etc-pam-d-sudo" tabindex="-1">配置 /etc/pam.d/sudo <a class="header-anchor" href="#配置-etc-pam-d-sudo" aria-label="Permalink to “配置 /etc/pam.d/sudo”">​</a></h3><p>現在要去驗證配置是否有效，<strong>在同一個終端窗口中</strong>，你需要設置 <code>sudo</code> 來要求使用 Yubikey 的詢問-響應。將下面這幾行插入到 <code>/etc/pam.d/sudo</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth required pam_yubico.so mode=challenge-response</span></span></code></pre></div><p>將上面的 <code>auth</code> 行插入到文件中的 <code>auth include system-auth</code> 行的上面，然後保存並退出編輯器。在默認的 Fedora 29 設置中，<code>/etc/pam.d/sudo</code> 應該像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#%PAM-1.0</span></span>
<span class="line"><span>auth required pam_yubico.so mode=challenge-response</span></span>
<span class="line"><span>auth include system-auth</span></span>
<span class="line"><span>account include system-auth</span></span>
<span class="line"><span>password include system-auth</span></span>
<span class="line"><span>session optional pam_keyinit.so revoke</span></span>
<span class="line"><span>session required pam_limits.so</span></span>
<span class="line"><span>session include system-auth</span></span></code></pre></div><p><strong>保持這個初始的終端窗口打開</strong>，然後打開一個新的終端窗口進行測試，在新的終端窗口中輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo echo testing</span></span></code></pre></div><p>你應該注意到了 Yubikey 上的 LED 在閃爍。點擊 Yubikey 按鈕，你應該會看見一個輸入 <code>sudo</code> 密碼的提示。在你輸入你的密碼之後，你應該會在終端屏幕上看見 “testing” 的字樣。</p><p>現在去測試確保失敗也正常，啓動另一個終端窗口，並從 USB 插口中拔掉 Yubikey。使用下面這條命令驗證，在沒有 Yubikey 的情況下，<code>sudo</code> 是否會不再正常工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo echo testing fail</span></span></code></pre></div><p>你應該立刻被提示輸入 <code>sudo</code> 密碼，但即使你輸入了正確密碼，登錄也應該失敗。</p><h3 id="設置-gnome-桌面管理器-gdm" tabindex="-1">設置 Gnome 桌面管理器（GDM） <a class="header-anchor" href="#設置-gnome-桌面管理器-gdm" aria-label="Permalink to “設置 Gnome 桌面管理器（GDM）”">​</a></h3><p>一旦你的測試完成後，你就可以為圖形登錄添加詢問-響應支持了。將你的 Yubikey 再次插入進 USB 插口中。然後將下面這幾行添加到 <code>/etc/pam.d/gdm-password</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth required pam_yubico.so mode=challenge-response</span></span></code></pre></div><p>打開一個終端窗口，然後運行下面這些命令。如果需要，你可以使用其他的編輯器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/pam.d/gdm-password</span></span></code></pre></div><p>你應該看到 Yubikey 上的 LED 在閃爍，按下 Yubikey 按鈕，然後在提示符處輸入密碼。</p><p>修改 <code>/etc/pam.d/gdm-password</code> 文件，在已有的 <code>auth substack password-auth</code> 行上添加新的行。這個文件的頂部應該像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth [success=done ignore=ignore default=bad] pam_selinux_permit.so</span></span>
<span class="line"><span>auth required pam_yubico.so mode=challenge-response</span></span>
<span class="line"><span>auth substack password-auth</span></span>
<span class="line"><span>auth optional pam_gnome_keyring.so</span></span>
<span class="line"><span>auth include postlogin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>account required pam_nologin.so</span></span></code></pre></div><p>保存更改並退出編輯器，如果你使用的是 vi，輸入鍵是按 <code>Esc</code> 鍵，然後在提示符處輸入 <code>wq!</code> 來保存並退出。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>現在註銷 GNOME。將 Yubikey 插入到 USB 口，在圖形登錄界面上點擊你的用户名。Yubikey LED 會開始閃爍。觸摸那個按鈕，你會被提示輸入你的密碼。</p><p>如果你丟失了 Yubikey，除了重置密碼之外，你還可以使用備份的 Yubikey。你還可以給你的賬户增加額外的 Yubikey 配置。</p><p>如果有其他人獲得了你的密碼，他們在沒有你的物理硬件 Yubikey 的情況下，仍然不能登錄。恭喜！你已經顯著提高了你的工作環境登錄的安全性了。</p><hr>`,53)),t("p",null,[e[3]||(e[3]=s("via: ",-1)),i(a,{href:"https://fedoramagazine.org/login-challenge-response-authentication/"},{default:n(()=>[...e[2]||(e[2]=[s("https://fedoramagazine.org/login-challenge-response-authentication/",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=s("作者：",-1)),i(a,{href:"https://fedoramagazine.org/author/nabooengineer/"},{default:n(()=>[...e[4]||(e[4]=[s("nabooengineer",-1)])]),_:1}),e[9]||(e[9]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[5]||(e[5]=[s("lujun9972",-1)])]),_:1}),e[10]||(e[10]=s(" 譯者：",-1)),i(a,{href:"https://github.com/hopefully2333"},{default:n(()=>[...e[6]||(e[6]=[s("hopefully2333",-1)])]),_:1}),e[11]||(e[11]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[12]||(e[12]=[s("LCTT",-1)])]),_:1}),e[15]||(e[15]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[13]||(e[13]=[s("Linux中國",-1)])]),_:1}),e[16]||(e[16]=s(" 榮譽推出",-1))])])}const v=p(h,[["render",c]]);export{C as __pageData,v as default};
